    "I2": [
      "Medication-induced diarrhoea (e.g., inhaled β-agonist systemic effect or contaminant): patient suspects inhaler; physiologically unlikely but considered.",
      "Food-borne toxin (pre-formed toxin from Staph aureus, Bacillus cereus) causing vomiting/diarrhoea within hours of ingestion."
    ],
    "C": [
      "Coeliac disease: immune-mediated malabsorption presenting with chronic diarrhoea."
    ],
    "A": [
      "Inflammatory bowel disease (Crohn’s/UC): can flare with diarrhoea and crampy pain; usually chronic, may show blood/mucus.",
      "Food allergy (e.g., fructose intolerance) precipitating loose stools."
